/** True when (x, z) is on or right beside a collider. Outside the grid counts as clear (the bounds clamp handles that). */
export function seedSpotBlocked(x: number, z: number): boolean {
  const row = ROWS[Math.floor((z - Z0) / CELL)]
  return row !== undefined && row[Math.floor((x - X0) / CELL)] === '#'
}
